export interface CallInput {
  user?: UserContext;
  body?: unknown;
  query?: Record<string, unknown>;
  params?: Record<string, string>;
  setup?: (store: FakeStore) => void;
}

export interface HappyCase extends CallInput {
  /** Exact expected response body (evaluated after the call). */
  expected: (store: FakeStore) => unknown;
  /** Extra assertions on the store after the call. */
  after?: (store: FakeStore) => void;
}

export interface NotApplicable {
  na: string;
}

export type ErrorCase = CallInput | NotApplicable;

export interface RouteCase {
  happy: HappyCase;
  errors?: Partial<Record<number, ErrorCase>>;
  /**
   * The route is registered with RBAC + validation but its handler is a stub
   * that answers 501 NOT_IMPLEMENTED (reason names the session that implements
   * it). routes.contract.test.ts then expects 501 for the happy input instead of
   * the contract status; remove `stub` and fill in `expected` when it lands.
   */
  stub?: string;
}

export const isNa = (c: ErrorCase | undefined): c is NotApplicable => !!c && 'na' in c;

/**
 * How each listed error status is exercised in-process:
 *   case      — explicit input in ROUTE_CASES
 *   generated — 401 (no identity), 403 (one role below), 500 (data layer throws)
 *   na        — cannot occur for this route; `reason` says why
 *   missing   — no way to test it (coverage.contract.test.ts fails)
 */
export type ErrorPlanKind = 'case' | 'generated' | 'na' | 'missing';
export interface ErrorPlanEntry {
  kind: ErrorPlanKind;
  reason?: string;
}

export function errorPlan(
  c: { role: string; errors: readonly number[] },
  rc: RouteCase | undefined,
): Record<number, ErrorPlanEntry> {
  const plan: Record<number, ErrorPlanEntry> = {};
  for (const status of c.errors) {
    const explicit = rc?.errors?.[status];
    if (isNa(explicit)) plan[status] = { kind: 'na', reason: explicit.na };
    else if (explicit) plan[status] = { kind: 'case' };
    else if (status === 401 || status === 500) plan[status] = { kind: rc ? 'generated' : 'missing' };
    else if (status === 403 && (c.role === 'steward' || c.role === 'admin')) plan[status] = { kind: rc ? 'generated' : 'missing' };
    else if (status === 403) plan[status] = { kind: 'na', reason: 'route role is reviewer: every authenticated caller passes the role check' };
    else plan[status] = { kind: 'missing' };
  }
  return plan;
}

